const APP_CACHE = `moleculium-app-${VERSION}`;
const RUNTIME_CACHE = 'moleculium-runtime-v1';
const DATA_CACHE = 'moleculium-data-v1';
const LIVE_CACHE = 'moleculium-live-v1';
const IMAGE_CACHE = 'moleculium-images-v1';
const LIMITS = { [LIVE_CACHE]: 600, [IMAGE_CACHE]: 500, [RUNTIME_CACHE]: 120 };
const LIVE_HOSTS = [
  'pubchem.ncbi.nlm.nih.gov',
  'www.wikidata.org',
  'query.wikidata.org',
  'commons.wikimedia.org',
];
const IMAGE_HOSTS = ['upload.wikimedia.org', 'thumb.wikimedia.org'];

self.addEventListener('install', event => {
  event.waitUntil(
    caches
      .open(APP_CACHE)
      .then(cache => cache.addAll(PRECACHE.map(path => new Request(path, { cache: 'reload' }))))
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    (async () => {
      const keep = new Set([APP_CACHE, RUNTIME_CACHE, DATA_CACHE, LIVE_CACHE, IMAGE_CACHE]);
      for (const key of await caches.keys())
        if (key.startsWith('moleculium-') && !keep.has(key)) await caches.delete(key);
      await self.clients.claim();
    })()
  );
});

self.addEventListener('message', event => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

async function trim(cacheName) {
  const limit = LIMITS[cacheName];
  if (!limit) return;
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - limit; i++) await cache.delete(keys[i]);
}

const timeout = ms => new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms));

/** Network first (fresh when online), falling back to the last good copy. */
async function networkFirst(request, cacheName, wait = 10000) {
  const cache = await caches.open(cacheName);
  try {
    const response = await Promise.race([fetch(request), timeout(wait)]);
    if (response.ok) cache.put(request, response.clone()).then(() => trim(cacheName));
    return response;
  } catch (error) {
    const cached = await cache.match(request, { ignoreVary: true });
    if (cached) return cached;
    throw error;
  }
}

/** Cache first, refreshed in the background (app files that change between versions). */
async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  const refresh = fetch(request)
    .then(response => {
      if (response.ok) cache.put(request, response.clone()).then(() => trim(cacheName));
      return response;
    })
    .catch(() => cached);
  return cached || refresh;
}

/** Images: cache first, fetched with CORS so cached entries stay small. */
async function imageCacheFirst(request) {
  const cache = await caches.open(IMAGE_CACHE);
  const cached = await cache.match(request.url);
  if (cached) return cached;
  try {
    const response = await fetch(request.url, { mode: 'cors', credentials: 'omit' });
    if (response.ok) cache.put(request.url, response.clone()).then(() => trim(IMAGE_CACHE));
    return response;
  } catch {
    return fetch(request);
  }
}

self.addEventListener('fetch', event => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);

  if (url.origin === self.location.origin) {
    if (request.mode === 'navigate') {
      event.respondWith(networkFirst(request, APP_CACHE, 5000).catch(() => caches.match('index.html')));
      return;
    }
    // Reference data and the PubChem proxy: fresh when online, cached for offline use.
    if (url.pathname.includes('/data/') || url.pathname.includes('/api/')) {
      event.respondWith(networkFirst(request, url.pathname.includes('/api/') ? LIVE_CACHE : DATA_CACHE));
      return;
    }
    event.respondWith(
      caches
        .match(request, { ignoreSearch: true })
        .then(hit => hit || staleWhileRevalidate(request, RUNTIME_CACHE))
    );
    return;
  }
  if (url.hostname === 'pubchem.ncbi.nlm.nih.gov' && url.pathname.endsWith('/PNG')) {
    event.respondWith(imageCacheFirst(request));
    return;
  }
  if (LIVE_HOSTS.includes(url.hostname) || url.hostname.endsWith('.wikipedia.org')) {
    event.respondWith(networkFirst(request, LIVE_CACHE));
    return;
  }
  if (IMAGE_HOSTS.includes(url.hostname)) event.respondWith(imageCacheFirst(request));
});
